/* ROUND ONCE PER CASCADE, NOT PER STAGE (PW ruling 2026-09-02, D5
 * amendment; landed 2026-09-03).
 *
 * The per-stage SATURATE is deleted from the fixed cascade kernels. The
 * per-stage ERROR FEEDBACK is NOT -- they are two separate deletions and
 * RIG C measured them as costing wildly different things: the saturate
 * is six instructions and, while nothing overflows, costs nothing
 * numerically at all, because a saturate that never fires is the
 * identity; the error feedback is ONE instruction and is worth 16 dB of
 * LF response on the +15 dB Q3.16 20 Hz shelf D5 was decided on.
 *
 * DSP4_BQ_ROUNDONCE=0 is the CONTROL and it is the per-stage-saturating
 * contract kernel byte for byte. bqeverify.sh needs both: built at 0 it
 * diffs the contract against the round-once arm and the divergences must
 * be exactly the ones fixed_ref predicts; built at 1 the two arms must
 * agree on every word of every vector.
 *
 * What this gives up is the overflow GUARANTEE, and only that. Headroom
 * sized per cascade on |h|_1 at parameter-load time is the guard that
 * keeps the cycles; see MW/D32/DSP/dsp4-roundonce-land-20260903.md. */
#ifndef DSP4_BQ_ROUNDONCE
#define DSP4_BQ_ROUNDONCE 1
#endif

/* THE PER-CASCADE HEADROOM GUARD (2026-09-03), which is what buys the
 * overflow guarantee back.
 *
 * H = ceil(log2(|h|_1 / 8)) bits, sized over the worst PARTIAL cascade
 * at PARAMETER-LOAD time (lib/bq_headroom.asm; model
 * tools/dsp/bq_h_load.py) and carried as the FIRST WORD of the cascade's
 * coefficient block. The kernels shift the cascade input down H on entry
 * and the output back up and saturate ONCE on exit; the recursion runs
 * at the scaled level where |h|_1 * x fits Q4.28 and only the word
 * handed on comes back up.
 *
 * H = 0 FOR 94% OF THE DEFS SPACE, and there both scaling passes are
 * jumped over whole -- the sample loop is byte for byte the unguarded
 * one. It is inseparable from round-once and is defined to follow it:
 * with the per-stage saturate in place there is nothing to guard, and
 * DSP4_BQ_ROUNDONCE=0 must stay the byte-for-byte contract control that
 * every bar is run against.
 *
 * DSP4_BQ_GUARD_FORCE > 0 overrides the sized H on EVERY cascade, which
 * is how the guard's worst-case cost is measured in the graph rather
 * than estimated from a rig. It is a measurement, not a mode. */
/* FLOAT ON SHARC -- DSP4_BQ_FLOAT, THE SHIPPING CASCADE (PW ruling
 * 2026-09-03: the SHARC DSP is 40-bit float). DEFAULTS ON.
 *
 * The four cascade kernels are software FLOAT DF-II-T instead of the
 * Q4.28 offset form, and the cascade's coefficient block carries FIVE
 * float32 words a stage in D5's OWN OFFSET ENCODING -- b0, n1 = b1+2*b0,
 * n2 = b2-b0, c1 = 2+a1, c2 = 1-a2 -- which the kernel reconstructs in
 * registers once per stage per block. `_bq_fx_convert_N` is a COPY: the
 * wire word IS the stored word, and the Q4.28 quantisation step is gone.
 * The signal buffers stay Q4.28: the conversion is ONE instruction per
 * sample on the way into a cascade (`Fn = FLOAT Rx BY -28`) and one on
 * the way out (`Rn = FIX Fx BY 28`, after the one CLIP, because the
 * inter-node bus is still Q4.28).
 *
 * THE OFFSET WIRE IS THE ACCURACY, NOT A DETAIL. Direct float32
 * coefficients cost 0.3715 dB on the DEFS worst set -- eight times the
 * 0.046 dB golden bar -- because a1 = -1.9948 has a 2.4e-7 ulp in
 * float32 against Q4.28's 3.7e-9, six bits on the number that places
 * the pole. On the offset wire the same arithmetic reads 0.0080 dB,
 * better than the fixed contract's 0.0265.
 *
 * IT NEEDS NONE OF THE GUARD MACHINERY: no per-stage saturate, no
 * 64-bit extract, no |h|_1 headroom guard and no load-time sizer,
 * because an 8-bit exponent absorbs the |h|_1 = 1313 (+62 dB) worst
 * case that costs the fixed path eight bits of mantissa (proved, not
 * asserted: peak 1285.0 against 3.4e38). DSP4_BQ_GUARD is therefore
 * FORCED OFF here (and DSP4_BQ_HDR with it) rather than merely
 * defaulting off.
 *
 * THE STATE IS 40-BIT. MODE1.RND32 is CLEARED, so the register file
 * carries the SHARC's extended-precision float -- eight more mantissa
 * bits -- through the whole recursion, and the block kernels hold w1/w2
 * in registers across all DSP4_BLOCK_SIZE samples, which is where a
 * high-Q low-frequency biquad's state error accumulates. It costs
 * nothing: one `bit clr` against one `bit set` in the same place.
 * DSP4_BQ_FLOAT32=1 is the CONTROL: RND32 set, so every result rounds at
 * the 32-bit boundary and the arm is IEEE single throughout -- RIG A2
 * exactly. The difference between the two is what the 40 bits buy
 * (33-48 dB of noise floor at zero cycle cost).
 *
 * DSP4_BQ_FLOAT=0 IS THE FIXED REFERENCE MODEL AND IT STAYS. The
 * round-once path and its guard are what a future FPGA fixed engine
 * follows; the fixed build must keep rebuilding its recorded W0
 * witnesses byte for byte, and that is the bar that proves it intact.
 * Do not delete them. */
#ifndef DSP4_BQ_FLOAT
#define DSP4_BQ_FLOAT 1
#endif
#ifndef DSP4_BQ_FLOAT32
#define DSP4_BQ_FLOAT32 0
#endif

#if DSP4_BQ_ROUNDONCE && !DSP4_BQ_FLOAT
#ifndef DSP4_BQ_GUARD
#define DSP4_BQ_GUARD 1
#endif
#else
#undef DSP4_BQ_GUARD
#define DSP4_BQ_GUARD 0
#endif
#ifndef DSP4_BQ_GUARD_FORCE
#define DSP4_BQ_GUARD_FORCE 0
#endif

/* THE ROUTING CROSSPOINT ACCUMULATE -- MEASUREMENT ARM ONLY.
 * DSP4_RTG_NOACC=1 deletes the per-strip crosspoint accumulate and leaves
 * every other part of ROUTING in place, so the whole-graph difference
 * against the default is that accumulate's cost and nothing else. The bus
 * accumulators stay at zero under it, so the audio is silence by
 * construction -- a price tag, not a mode. */
#ifndef DSP4_RTG_NOACC
#define DSP4_RTG_NOACC 0
#endif

/* THE BUS-MAJOR CROSSPOINT FABRIC (2026-09-03, review finding D22).
 * ROUTING stops walking its own crosspoints sample by sample and publishes
 * a COLUMN of a bus-major coefficient matrix instead; one shared pass
 * (rtg_fabric.asm) then loads each bus accumulator ONCE per sample and MACs
 * every strip that feeds it into the live MRF. Exact, not approximate: the
 * accumulate is 80-bit integer with no rounding before readout, so the sum
 * is order-independent (busgold.sh is the proof, not this comment).
 *
 * FORCED OFF without block kernels, which is what keeps the shipping
 * per-sample image -- every recorded W0 witness -- byte for byte. There is
 * no per-sample form of this: the whole point is amortising a per-BLOCK
 * accumulator load over the strips that share it.
 *
 * DSP4_RTG_FABRIC=0 is the CONTROL and rebuilds the per-strip accumulate
 * byte for byte. */
#ifndef DSP4_RTG_FABRIC
#define DSP4_RTG_FABRIC 1
#endif
#if !DSP4_BLOCK_KERNELS
#undef DSP4_RTG_FABRIC
#define DSP4_RTG_FABRIC 0
#endif

/* THE DELAY LINE'S TWO PASSES (2026-09-03, review finding D25's remainder).
 * The block kernel wrote one sample to the delay line and then read another
 * from it, per sample, and the delay lines are in L2 -- session 3 measured
 * DLY at 63 cycles/sample of which only 8.4 was address arithmetic. Writing
 * the whole block and then reading the whole block is the same arithmetic in
 * two sequential bursts; it is bit-exact for the reason written out at the
 * loop. DSP4_DLY_SPLIT=0 is the CONTROL and rebuilds the interleaved loop
 * byte for byte.
 *
 * DSP4_DLY_NOMEM is a MEASUREMENT ARM on the control loop: it deletes the
 * delay line's READ and keeps everything else, so the whole-graph difference
 * prices the L2 traffic. The audio is wrong by design under it. */
#ifndef DSP4_DLY_SPLIT
#define DSP4_DLY_SPLIT 1
#endif
#ifndef DSP4_DLY_NOMEM
#define DSP4_DLY_NOMEM 0
#endif

/* D20's REMAINING FOLD, PRICED (2026-09-03). Folding GAIN into FILT deletes
 * GAIN's store into the chain ping-pong and NOTHING ELSE: the round and the
 * saturate feed the post-trim TAP, which PW ruled stays (2026-08-29, and
 * again with the float landing) because the ROUTER reads it as pickoff 0.
 * DSP4_GAIN_NOCHAIN=1 replaces that store with a nop -- the same instruction
 * count the fold would reach, without building the fold -- so the whole-graph
 * difference is the fold's CEILING, measured rather than counted. FILT then
 * reads a stale block, which costs the same cycles (a biquad's cost is
 * data-independent) and is wrong by design: a price tag, not a mode. */
#ifndef DSP4_GAIN_NOCHAIN
#define DSP4_GAIN_NOCHAIN 0
#endif

/* Header words in front of a cascade's coefficients: 1 with the guard,
 * 0 without. The interleaved pair blocks carry two, one per strip. */
/* GAIN ON THE FLOAT PATH -- DSP4_GAIN_FLOAT, and it follows the cascade.
 *
 * `_gsimd_gain_blk` (lib/meter_fx.asm) is the block kernel every one of
 * the 32 metered GAIN nodes runs, and it is where all of the graph's
 * GAIN cycles are. Under this flag its AUDIO path becomes one float
 * multiply, one CLIP and one FIX in place of the 64-bit extract and the
 * branch-free saturate -- eighteen instructions per two samples become
 * eleven.
 *
 * THE METER STAYS FIXED, AND THAT IS NOT A COMPROMISE. The meter wants
 * the PRE-CLIP wide word and an EXACT sum of squares across the block:
 * `mrb = x*g (ssi)` gives it the full Q8.24 over-range the 32-bit store
 * cannot hold, and MRF accumulates 80 bits with no rounding and no
 * saturation, which is order-independent and is what makes the SIMD
 * split exact. Float would make both approximate to buy back two
 * instructions. So the wide MAC stays and only the audio word changes,
 * and the gain the audio uses is FLOATed from the same Q4.28 word the
 * meter's MAC uses -- polarity and mute already folded in -- so the two
 * cannot disagree about what gain was applied.
 *
 * The scalar body, the DSP4_GAIN_SIMD=0 body and the DSP4_MTR_OFF body
 * stay FIXED and are the byte-for-byte controls they always were.
 *
 * Defaults to DSP4_BQ_FLOAT, so DSP4_BQ_FLOAT=0 is still the whole fixed
 * reference model in one flag. */
#ifndef DSP4_GAIN_FLOAT
#define DSP4_GAIN_FLOAT DSP4_BQ_FLOAT
#endif

/* MODE1.RND32, bit 16: set = every float result rounds at the 32-bit
 * boundary (IEEE single), clear = the register file's 40-bit extended
 * format. This firmware has never written it, so the part boots in
 * 40-bit mode; every kernel that touches it saves and restores MODE1. */
#define DSP4_RND32_BIT 0x00010000

#define DSP4_BQ_HDR DSP4_BQ_GUARD

/* Samples of the load-time impulse run per main-loop pass. The sizing
 * is spent out of the idle spin between blocks and never out of block
 * work; this is what bounds how much of one pass it can take. */
#ifndef DSP4_BQHR_BUDGET
#define DSP4_BQHR_BUDGET 128
#endif

