/* CFG_CHAN_MASK / CFG_AUX_MASK GET READERS (2026-09-09).
 *
 * The host has always sent D24 a CHAN_MASK of 0x00FFFFFF ("strips 25-32
 * NET-only") and an AUX_MASK, product_config.asm has always stored both,
 * and until this flag NOTHING READ EITHER. A D24 therefore ran all 32
 * channel strips and summed all 32 into the main bus -- measured on the
 * part 2026-09-09 as C2_MAIN_ST_OUT sitting at positive full scale for
 * 48,000 frames of 48,000 with every cell the D24 contract can reach
 * already silenced (MW/D32/DSP/dsp4-loop-latency-20260909.md section 3).
 *
 * The mask is applied by SKIPPING, not by silencing: a masked strip's
 * nodes are never called, so the cycles come back as well as the audio.
 * That is the whole point -- a D24 is a 24-channel product and its load
 * must be a 24-channel load.
 *
 * DSP4_CHAN_MASK=0 IS THE CONTROL and rebuilds the pre-fix chain byte
 * for byte: no gate is emitted, _mask_apply latches the live words and
 * silences nothing, and every recorded cycle figure taken before this
 * flag existed is reproducible. It is not a mode -- a 0 build is the
 * defect. */
#ifndef DSP4_CHAN_MASK
#define DSP4_CHAN_MASK 1
#endif

/* THE AUX_INPUT BYPASS (S32). A PROPOSAL, DEFAULT OFF.
 *
 * Chip 2 carries twelve AUX_INPUT nodes -- the eight D32 snake returns and
 * the codec, Pi, USB and BT feeds -- and every one of them comes up with
 * `on = 0`. S29 measured the D32 scope class at 3.43-3.69 points of chip 2
 * and found the expensive half of it to be these nodes being CALLED while
 * switched off: the block wrapper stages BLOCK samples through a call/rts
 * pair each to multiply them by a coefficient the `on` cell has already
 * forced to zero.
 *
 * With this on, a switched-off AUX_INPUT publishes one block of silence (the
 * park, S23 gate 2's mechanism) and the chain then stops calling it at all
 * until `on` goes back to 1 -- six instructions a node a block against about
 * 1,100 cycles. The node is REACHED AGAIN ON THE BLOCK ITS CELL FLIPS,
 * because the gate reads the same `on` word the host writes; there is no
 * config word and no commit in the path.
 *
 * 0 EMITS NOT ONE BYTE, which is the point of the guard: the window
 * candidate rebuilds byte for byte with this at its default, and the arm
 * that carries it is a pair of its own. */
#ifndef DSP4_AUXIN_BYPASS
#define DSP4_AUXIN_BYPASS 0
#endif

/* THE CHANNEL MATRIX SEND SPI BLOCK (S22-4).
 *
 * spi_handler.asm bumps _ctl_epoch[addr / 144] so a strip node
 * re-preps when the host writes into that strip's page, and it
 * clamps everything at or above 4608 into slot 32 -- a catch-all
 * no strip node watches. The matrix send cells are deliberately
 * OUTSIDE the 144-word page: putting them inside would have moved
 * every chip-1 address above channel 1's routing node, the whole
 * map, the MCU's ghost table and every stored golden, for four
 * words. Without this range every matrix write landed in the
 * catch-all, the ROUTING node never re-prepped, and its matrix
 * crosspoint coefficient stayed at zero -- measured on the part,
 * a strip driven to 0x0D39B767 post-fader against a matrix bus of
 * exactly zero with the send both ON and OFF.
 *
 * READ OFF THE GRAPH, never typed. The block is contiguous and
 * strip-ordered, so the strip index is (addr - BASE) >> SHIFT. */
#define DSP4_CTL_MTX_BASE   4806
#define DSP4_CTL_MTX_WORDS  4
#define DSP4_CTL_MTX_SHIFT  2
#define DSP4_CTL_MTX_SPAN   128

#endif /* DSP4_BLOCK_H */
